window.initWordle=()=>{gameScore.style.display="none",setStatus("Guess the 5-letter word!","var(--text-main)");const e=["APPLE","BRAVE","CHAIR","DANCE","EAGLE","FLAME","GRAPE","HEART","IGLOO","JUICE","KNIFE","LEMON","MOUSE","NIGHT","OCEAN","PIZZA","QUEEN","RIVER","SNAKE","TRAIN","UMBRA","VOICE","WATER","XENON","YACHT","ZEBRA","REACT","GHOST","BLAME","SKILL"],t=e[Math.floor(Math.random()*e.length)],s=document.createElement("div"),a=document.createElement("div");a.className="wordle-board";const l=[];for(let e=0;e<6;e++){const e=document.createElement("div");e.className="wordle-row";const t=[];for(let s=0;s<5;s++){const s=document.createElement("div");s.className="wordle-cell",t.push(s),e.appendChild(s)}l.push(t),a.appendChild(e)}s.appendChild(a),gameArea.appendChild(s);let n=0,o=0,r=!1;const d=()=>{const e=l[n].map(e=>e.innerText).join("");let s=t.split(""),a=e.split("");for(let e=0;e<5;e++)a[e]===s[e]&&(l[n][e].classList.add("correct"),s[e]=null,a[e]=null);for(let e=0;e<5;e++)if(null!==a[e]){const t=s.indexOf(a[e]);-1!==t?(l[n][e].classList.add("present"),s[t]=null):l[n][e].classList.add("absent")}e===t?(r=!0,setStatus("You Won! 🎉","var(--snake-color)"),SFX.play("win")):(n++,o=0,6===n&&(r=!0,SFX.play("lose"),setStatus(`Game Over! Word was ${t}`,"var(--x-color)")))};addListener(document,"keydown",e=>{r||("Enter"===e.key?5===o?d():(SFX.play("word-wrong"),setStatus("Not enough letters","var(--text-muted)"),setTimeout(()=>setStatus("Guess the 5-letter word!","var(--text-main)"),1500)):"Backspace"===e.key||"Delete"===e.key?o>0&&(SFX.play("key-press"),o--,l[n][o].innerText=""):/^[a-zA-Z]$/.test(e.key)&&1===e.key.length&&o<5&&(SFX.play("key-press"),l[n][o].innerText=e.key.toUpperCase(),o++))})};